#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_path_parses() {
        for icon in Icon::ALL.into_iter().chain([Icon::Chevron, Icon::Speaker { waves: 1, muted: false }]) {
            for (parts, _) in layers(icon).0 {
                for (d, _) in parts {
                    assert!(svgpath::parse_ok(d), "{icon:?}: {d}");
                }
            }
        }
    }
}
